# The formula of wassup, generated by wassup's scripts/formula.sh from the checksums of
# its 0.1.2 release, whose archives are copied to a wassup-<version> release of this
# repository (wassup's repository is private). Never edited by hand.
class Wassup < Formula
  desc "Laptop update routine, with the chezmoi repository as the source of truth"
  # wassup's repository is private, and brew audit requires a homepage that answers.
  homepage "https://github.com/FunDrivenDev/homebrew-tap"
  version "0.1.2"

  depends_on :macos

  on_macos do
    on_arm do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/wassup-#{version}/wassup_#{version}_darwin_arm64.tar.gz"
      sha256 "304c479bd5198684c01c22625e16703b7271d1e970208f67fa095b924e106a33"
    end
    on_intel do
      url "https://github.com/FunDrivenDev/homebrew-tap/releases/download/wassup-#{version}/wassup_#{version}_darwin_amd64.tar.gz"
      sha256 "786182f287746e6d97ea304bbb64d2d83e38e84dae7fd6576c220895c5232274"
    end
  end

  def install
    bin.install "wassup"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wassup --version")
  end
end
